// ─────────────────────────────────────────────────────────────
//  CONFIGURACIÓN · edita este nodo para adaptarlo a tu perfil
// ─────────────────────────────────────────────────────────────
return [{
  json: {
    // Lo que lee la IA para decidir si una oferta encaja contigo
    perfil: `Estudiante de 2º de DAW (Desarrollo de Aplicaciones Web) en Valencia, España.
Busco mi primer empleo o prácticas como desarrollador web junior.
Stack: PHP (Laravel), JavaScript, HTML, CSS, SQL (MySQL/PostgreSQL), Java básico.
También: Docker, Git, CI/CD con Jenkins, nociones de AWS y Big Data.
Idiomas: español nativo, inglés técnico.
Prefiero remoto o presencial/híbrido en Valencia.`,

    // Filtro previo barato (sin IA): al menos una debe aparecer en título, etiquetas o descripción
    palabrasClave: ['php', 'laravel', 'javascript', 'typescript', 'frontend', 'front-end',
      'backend', 'back-end', 'full stack', 'fullstack', 'web developer', 'vue', 'react',
      'node', 'sql', 'java'],

    // Si el título contiene alguna, se descarta directamente
    excluirTitulo: ['senior', 'sr.', 'sr ', 'lead', 'staff', 'principal', 'head of',
      'manager', 'architect', 'director', 'vp '],

    // Ubicaciones aceptadas (se compara en minúsculas). Las ofertas remotas sin restricción también pasan.
    ubicaciones: ['worldwide', 'anywhere', 'europe', 'emea', 'spain', 'españa', 'valencia',
      'madrid', 'barcelona', 'cet', 'eu'],

    puntuacionMinima: 6,      // de 0 a 10: a partir de aquí sale en el resumen
    maxPorEjecucion: 25,      // tope de ofertas que se mandan a la IA por ejecución

    // Por dónde te llegan los avisos: 'whatsapp' (CallMeBot) o 'telegram'
    aviso: 'whatsapp',
    whatsappTelefono: '+34XXXXXXXXX',          // tu número, con prefijo de país
    telegramChatId: 'PON_AQUI_TU_CHAT_ID',     // solo si usas Telegram

    // Cualquier API compatible con OpenAI: Groq (gratis), OpenRouter, OpenAI, Ollama local...
    ia: {
      baseUrl: 'https://api.groq.com/openai/v1',
      modelo: 'openai/gpt-oss-120b',
    },
  },
}];

// Convierte las respuestas de cada fuente a un formato común y aplica el filtro previo.
const cfg = $('Configuración').first().json;

const limpiarHtml = (html = '') => String(html)
  .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<br\s*\/?>|<\/p>|<\/li>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#0?39;/g, "'")
  .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();

const aFecha = (v) => {
  if (v === undefined || v === null || v === '') return null;
  const d = typeof v === 'number' ? new Date(v * 1000) : new Date(v);
  return isNaN(d) ? null : d.toISOString();
};

const desdeRemotive = (j) => ({
  fuente: 'remotive',
  id_externo: String(j.id),
  titulo: j.title,
  empresa: j.company_name ?? null,
  ubicacion: j.candidate_required_location || 'Remote',
  remoto: true,
  url: j.url,
  etiquetas: Array.isArray(j.tags) ? j.tags : [],
  descripcion: limpiarHtml(j.description),
  publicada_en: aFecha(j.publication_date),
});

const desdeArbeitnow = (j) => ({
  fuente: 'arbeitnow',
  id_externo: String(j.slug ?? j.url),
  titulo: j.title,
  empresa: j.company_name ?? null,
  ubicacion: j.location || (j.remote ? 'Remote' : null),
  remoto: Boolean(j.remote),
  url: j.url,
  etiquetas: [...(j.tags ?? []), ...(j.job_types ?? [])],
  descripcion: limpiarHtml(j.description),
  publicada_en: aFecha(j.created_at),
});

// 1. Normalizar todo lo que llega de las fuentes
const ofertas = [];
const errores = [];
for (const item of $input.all()) {
  const r = item.json;
  if (Array.isArray(r.jobs)) ofertas.push(...r.jobs.map(desdeRemotive));
  else if (Array.isArray(r.data)) ofertas.push(...r.data.map(desdeArbeitnow));
  else if (r.error) errores.push(r.error.message ?? String(r.error));
}

// 2. Filtro previo, sin gastar llamadas a la IA
const contiene = (texto, lista) => lista.some((p) => texto.includes(p));
const vistas = new Set();

const filtradas = ofertas.filter((o) => {
  if (!o.titulo || !o.url) return false;
  const clave = `${o.fuente}:${o.id_externo}`;
  if (vistas.has(clave)) return false;
  vistas.add(clave);

  const titulo = ` ${o.titulo.toLowerCase()} `;
  if (contiene(titulo, cfg.excluirTitulo)) return false;

  const texto = `${titulo} ${o.etiquetas.join(' ')} ${o.descripcion}`.toLowerCase();
  if (!contiene(texto, cfg.palabrasClave)) return false;

  const ubicacion = (o.ubicacion ?? '').toLowerCase();
  const ubicacionOk = contiene(ubicacion, cfg.ubicaciones)
    || (o.remoto && (ubicacion === '' || ubicacion === 'remote'));
  return ubicacionOk;
});

// Se manda todo en un solo item para insertarlo con una única consulta SQL
return [{
  json: {
    total_descargadas: ofertas.length,
    total_filtradas: filtradas.length,
    errores,
    ofertas: filtradas,
  },
}];

// Construye la petición a la IA para cada oferta nueva (modo: una vez por item).
const cfg = $('Configuración').first().json;
const o = $json;

const sistema = `Eres un reclutador técnico que evalúa ofertas de empleo para un candidato concreto.
Responde SOLO con un objeto JSON válido con estas claves:
{"puntuacion": entero 0-10, "nivel": "junior"|"mid"|"senior"|"desconocido",
 "tecnologias": [máximo 8 strings], "motivo": "una frase en español, máximo 160 caracteres"}
Criterios: 10 = encaja perfecto con su stack y nivel; 0 = nada que ver.
Penaliza mucho si pide más de 3 años de experiencia o un nivel senior.
Penaliza si exige residir en un país donde el candidato no puede trabajar.`;

const usuario = `PERFIL DEL CANDIDATO:
${cfg.perfil}

OFERTA:
Título: ${o.titulo}
Empresa: ${o.empresa ?? 'desconocida'}
Ubicación: ${o.ubicacion ?? 'desconocida'} ${o.remoto ? '(remoto)' : ''}
Etiquetas: ${(o.etiquetas ?? []).join(', ')}
Descripción:
${String(o.descripcion ?? '').slice(0, 3000)}`;

return {
  json: {
    id: o.id,
    peticion: {
      model: cfg.ia.modelo,
      temperature: 0.2,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: sistema },
        { role: 'user', content: usuario },
      ],
    },
  },
};

// Lee la respuesta de la IA y la valida (modo: una vez por item).
// Si la IA falla o devuelve algo raro, la oferta se guarda con puntuación null y se reintenta otro día.
const oferta = $('Preparar prompt').item.json;

let r = {};
try {
  const contenido = $json.choices?.[0]?.message?.content ?? '';
  // Algunos modelos envuelven el JSON en ```json ... ```
  const limpio = contenido.replace(/^```(?:json)?\s*|\s*```$/g, '').trim();
  r = JSON.parse(limpio);
} catch (e) {
  r = {};
}

const n = Number.parseInt(r.puntuacion, 10);
const puntuacion = Number.isFinite(n) ? Math.min(10, Math.max(0, n)) : null;
const niveles = ['junior', 'mid', 'senior', 'desconocido'];

return {
  json: {
    id: oferta.id,
    puntuacion,
    nivel: niveles.includes(r.nivel) ? r.nivel : 'desconocido',
    tecnologias: Array.isArray(r.tecnologias)
      ? r.tecnologias.filter((t) => typeof t === 'string').slice(0, 8)
      : [],
    motivo: typeof r.motivo === 'string' ? r.motivo.slice(0, 300) : null,
  },
};

// Monta el mensaje con las mejores ofertas del día, en formato WhatsApp o Telegram.
const cfg = $('Configuración').first().json;
const stats = $('Normalizar y filtrar').first().json;
const nuevas = $('Guardar nuevas').all().filter((i) => i.json.es_nueva === true).length;

const todas = $input.all().map((i) => i.json);
const buenas = todas
  .filter((o) => o.puntuacion !== null && o.puntuacion !== undefined && o.puntuacion >= cfg.puntuacionMinima)
  .sort((a, b) => b.puntuacion - a.puntuacion);
const sinPuntuar = todas.filter((o) => o.id && o.puntuacion === null).length;

const barra = (p) => '●'.repeat(p) + '○'.repeat(10 - p);

// Cada canal tiene su formato: WhatsApp usa *negrita* y _cursiva_; Telegram, HTML
const formatos = {
  whatsapp: {
    max: 1500, // CallMeBot manda el texto en la URL: mejor mensajes cortos
    maxOfertas: 5,
    esc: (s = '') => String(s).replace(/[*_~`]/g, ''),
    negrita: (s) => `*${s}*`,
    cursiva: (s) => `_${s}_`,
    enlace: (texto, url) => `${texto}\n🔗 ${url}`,
  },
  telegram: {
    max: 3900, // límite de Telegram: 4096
    maxOfertas: 10,
    esc: (s = '') => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'),
    negrita: (s) => `<b>${s}</b>`,
    cursiva: (s) => `<i>${s}</i>`,
    enlace: (texto, url) => `<a href="${url}">${texto}</a>`,
  },
};

const canal = cfg.aviso === 'telegram' ? 'telegram' : 'whatsapp';
const f = formatos[canal];

let texto = `🎯 ${f.negrita('Cazador de ofertas')}\n`
  + `${stats.total_descargadas} revisadas · ${stats.total_filtradas} pasan el filtro · `
  + `${nuevas} nuevas · ${f.negrita(`${buenas.length} encajan contigo`)}\n`;

if (sinPuntuar) texto += `\n⏳ La IA no pudo puntuar ${sinPuntuar} oferta(s); se reintentará en la próxima ejecución.\n`;
if (stats.errores?.length) {
  texto += `\n⚠️ Fuentes con error: ${f.esc(stats.errores.join(' | ')).slice(0, 300)}\n`;
}

for (const o of buenas.slice(0, f.maxOfertas)) {
  const bloque = `\n${f.negrita(`${o.puntuacion}/10`)} ${barra(o.puntuacion)}\n`
    + `${f.enlace(f.esc(o.titulo), f.esc(o.url))}\n`
    + `🏢 ${f.esc(o.empresa ?? '—')} · 📍 ${f.esc(o.ubicacion ?? '—')}\n`
    + (o.tecnologias?.length ? `🧰 ${f.esc(o.tecnologias.join(', '))}\n` : '')
    + (o.motivo ? `💬 ${f.cursiva(f.esc(o.motivo))}\n` : '');
  if (texto.length + bloque.length > f.max) break;
  texto += bloque;
}

if (buenas.length > f.maxOfertas) texto += `\n…y ${buenas.length - f.maxOfertas} más en la base de datos.`;
if (buenas.length === 0) texto += '\nHoy no hay nada que merezca la pena. Mañana más 💪';

return [{
  json: {
    canal,
    texto,
    telefono: cfg.whatsappTelefono,
    chatId: cfg.telegramChatId,
  },
}];
